using System.Windows; using TextBox=System.Windows.Controls.TextBox; using StackPanel=System.Windows.Controls.StackPanel; using TextBlock=System.Windows.Controls.TextBlock; using Button=System.Windows.Controls.Button; using Panel=System.Windows.Controls.Panel; using Control=System.Windows.Controls.Control; namespace CloudServer; public sealed class ServerSettingsDialog:Window { readonly TextBox listen=new(),publicUrl=new(); public string ListenPrefix=>listen.Text.Trim(); public string PublicBaseUrl=>publicUrl.Text.Trim().TrimEnd('/'); public ServerSettingsDialog(ServerSettings s){Title="Servereinstellungen";Width=600;Height=390;WindowStartupLocation=WindowStartupLocation.CenterOwner;var p=new StackPanel{Margin=new Thickness(30)};p.Children.Add(new TextBlock{Text="Netzwerk & HTTPS",FontSize=24,FontWeight=FontWeights.Bold});p.Children.Add(new TextBlock{Text="Die öffentliche Adresse sollte für produktiven Betrieb HTTPS verwenden. Ein TLS-Zertifikat muss in Windows für die gewählte HTTPS-Bindung eingerichtet sein.",TextWrapping=TextWrapping.Wrap,Margin=new Thickness(0,8,0,18)});Add(p,"Listener-Präfix (z. B. http://+:5050/ oder https://+:5051/)",listen);Add(p,"Öffentliche Basisadresse (z. B. https://cloud.example.de)",publicUrl);listen.Text=s.ListenPrefix;publicUrl.Text=s.PublicBaseUrl;var ok=new Button{Content="Speichern",Height=42,Margin=new Thickness(0,24,0,0)};ok.Click+=(_,__)=>{if(!Uri.TryCreate(ListenPrefix,UriKind.Absolute,out var a)||(a.Scheme!="http"&&a.Scheme!="https")){System.Windows.MessageBox.Show("Ungültiges Listener-Präfix.");return;}if(!Uri.TryCreate(PublicBaseUrl,UriKind.Absolute,out var b)||(b.Scheme!="http"&&b.Scheme!="https")){System.Windows.MessageBox.Show("Ungültige öffentliche Adresse.");return;}DialogResult=true;};p.Children.Add(ok);Content=p;}static void Add(Panel p,string l,Control c){p.Children.Add(new TextBlock{Text=l,Margin=new Thickness(0,10,0,4)});c.Height=34;p.Children.Add(c);} }